const incomingItems = $input.all();
const historyRows = incomingItems
  .map(item => item.json)
  .filter(row => row && !row.error && (row.content || row.created_at || row.timestamp || row.role));

if (historyRows.length === 0) {
  return { json: { formatted_history: [] } };
}

const sorted = historyRows.sort((a, b) => {
  const ta = new Date(a.created_at || a.timestamp || 0).getTime();
  const tb = new Date(b.created_at || b.timestamp || 0).getTime();
  return ta - tb;
});

const formattedHistory = sorted
  .slice(-20)
  .map(msg => ({
    role: msg.role === "assistant" ? "assistant" : "user",
    content: String(msg.content || "")
  }))
  .filter(msg => msg.content.trim() !== "");

return {
  json: {
    formatted_history: formattedHistory
  }
};

const assembled = $('Assemble Answer Facts').first().json || {};
const consultative = $('Consultative Reply Builder').first().json || {};
const incoming = $('Normalize Incoming Message').first().json || {};
const micro = $('Classify Conversation Micro Intent').first().json || {};

const userMessage = String(
  assembled.answer_facts?.userMessage ||
  assembled.raw_user_message ||
  incoming.userMessage ||
  ''
).trim();

const answerMode = String(assembled.answer_mode || 'normal_info');
const primaryFactType = String(assembled.primary_fact_type || 'general');
const primaryFactPayload = assembled.primary_fact_payload || {};
const fallbackFactPayload = assembled.fallback_fact_payload || {};

const shouldUseConsultativeStyle = !!consultative.should_use_consultative_style;
const consultativeReplyMode = String(consultative.consultative_reply_mode || 'normal_info');
const consultativeFacts = consultative.consultative_facts || {};
const safeGuidanceText = String(consultative.safe_guidance_text || '').trim();
const adminHandoffText = String(consultative.admin_handoff_text || '').trim();
const replyGuardrails = Array.isArray(consultative.reply_guardrails)
  ? consultative.reply_guardrails
  : [];

const isGreetingOnly = !!micro.is_greeting_only;
const isAcknowledgement = !!micro.is_acknowledgement;
const isJoinIntent = !!micro.is_join_intent;
const isClassDetailIntent = !!micro.is_class_detail_intent;
const isLocationIntent = !!micro.is_location_intent;
const isAdminIntent = !!micro.is_admin_intent;
const microIntent = String(micro.micro_intent || 'general_info');

let responseGoal = 'Jawab kebutuhan user dengan singkat, natural, dan akurat.';
let responseScope = 'Jawab hanya yang ditanyakan user.';
let styleMode = 'natural_admin_whatsapp';
let ctaMode = 'soft_optional';
let shouldMentionAdmin = false;
let shouldMentionForm = false;
let shouldOfferFollowUp = true;

if (isGreetingOnly || isAcknowledgement) {
  responseGoal = 'Balas secara ringan, hangat, dan singkat.';
  responseScope = 'Tidak perlu memberi informasi tambahan yang tidak diminta.';
  shouldOfferFollowUp = false;
}

if (answerMode === 'schedule_info') {
  responseGoal = 'Jawab pertanyaan jadwal secara jelas dan langsung.';
  responseScope = 'Fokus hanya pada jadwal kelas yang relevan.';
  shouldMentionAdmin = false;
  shouldMentionForm = false;
}

if (answerMode === 'coach_info') {
  responseGoal = 'Jawab pertanyaan tentang coach secara jelas dan relevan.';
  responseScope = 'Fokus pada info coach yang ditanyakan user.';
  shouldMentionAdmin = false;
  shouldMentionForm = false;
}

if (answerMode === 'class_detail') {
  responseGoal = 'Jelaskan kelas olahraga yang ditanyakan dengan natural dan membantu.';
  responseScope = 'Fokus pada deskripsi, manfaat, dan kecocokan kelas.';
  shouldMentionAdmin = false;
  shouldMentionForm = false;
}

if (
  answerMode === 'price_info' ||
  answerMode === 'promo_info' ||
  answerMode === 'event_info'
) {
  responseGoal = 'Jawab info harga, promo, atau event dengan jelas dan tidak bertele-tele.';
  responseScope = 'Fokus hanya pada data harga, promo, atau event yang relevan.';
  shouldMentionAdmin = false;
  shouldMentionForm = false;
}

if (
  answerMode === 'location_info' ||
  answerMode === 'admin_info' ||
  answerMode === 'about_info' ||
  answerMode === 'social_info' ||
  answerMode === 'registration_info' ||
  answerMode === 'consultation_info' ||
  answerMode === 'general_info'
) {
  responseGoal = 'Jawab pertanyaan informasi umum dengan natural dan seperlunya.';
  responseScope = 'Jangan melebar ke topik lain yang tidak diminta user.';
}

if (answerMode === 'join_info') {
  responseGoal = 'Jelaskan info join dengan ringkas dan mudah dipahami.';
  responseScope = 'Jelaskan alur join seperlunya tanpa langsung meminta data pendaftaran.';
  shouldMentionAdmin = false;
  shouldMentionForm = false;
  shouldOfferFollowUp = true;
}

if (answerMode === 'join_flow') {
  responseGoal = 'Bantu user lanjut ke proses pendaftaran karena niat join sudah jelas.';
  responseScope = 'Boleh arahkan ke langkah pendaftaran berikutnya.';
  shouldMentionAdmin = true;
  shouldMentionForm = true;
  shouldOfferFollowUp = false;
}

if (shouldUseConsultativeStyle) {
  styleMode = 'consultative_whatsapp_admin';
}

if (
  consultativeReplyMode === 'empathetic_handoff' ||
  consultativeReplyMode === 'careful_guidance'
) {
  shouldMentionAdmin = true;
}

const hardRules = [
  'Jawab berdasarkan fakta yang tersedia saja.',
  'Jangan menambah fakta baru.',
  'Jangan mengubah nama kelas, harga, promo, event, alamat, jadwal, coach, atau link.',
  'Jangan terdengar seperti robot atau template kaku.',
  'Jangan memberi lebih dari yang ditanyakan user.'
];

if (!shouldMentionAdmin) {
  hardRules.push('Jangan menyuruh hubungi admin resmi jika pertanyaan masih bisa dijawab langsung.');
}

if (!shouldMentionForm) {
  hardRules.push('Jangan meminta user isi data pendaftaran kecuali user sudah jelas mau join atau daftar.');
}

if (answerMode === 'schedule_info') {
  hardRules.push('Kalau pertanyaan tentang hari ini, tampilkan semua kelas hari itu yang tersedia di data.');
}

if (answerMode === 'join_info') {
  hardRules.push('Untuk info join, jangan langsung lempar ke form atau pendaftaran di awal.');
}

const humanizerHints = [
  'Gunakan bahasa Indonesia yang natural, sopan, dan hangat.',
  'Gunakan gaya chat admin WhatsApp, bukan brosur.',
  'Singkat, jelas, dan enak dibaca.',
  'Kalau ada sapaan, cukup satu saja.',
  'Hindari pengulangan yang kaku.'
];

return {
  json: {
    ...assembled,
    answerMode,
    primaryFactType,
    userMessage,

    build_context: {
      response_goal: responseGoal,
      response_scope: responseScope,
      style_mode: styleMode,
      cta_mode: ctaMode,
      should_mention_admin: shouldMentionAdmin,
      should_mention_form: shouldMentionForm,
      should_offer_follow_up: shouldOfferFollowUp
    },

    human_whatsapp_context: {
      userMessage,
      answerMode,
      primaryFactType,
      primaryFactPayload,
      fallbackFactPayload,
      consultativeReplyMode,
      consultativeFacts,
      safeGuidanceText,
      adminHandoffText,
      hardRules,
      humanizerHints,
      replyGuardrails
    }
  }
};

const ai =
  $('OpenAI Humanizer').first()?.json ||
  $('OpenAI Human Reply').first()?.json ||
  {};

function extractText(value) {
  if (!value) return '';

  if (typeof value === 'string') {
    return value.trim();
  }

  if (Array.isArray(value)) {
    const joined = value
      .map(extractText)
      .filter(Boolean)
      .join('\n')
      .trim();

    return joined;
  }

  if (typeof value !== 'object') {
    return '';
  }

  if (typeof value.output_text === 'string' && value.output_text.trim()) {
    return value.output_text.trim();
  }

  if (typeof value.text === 'string' && value.text.trim()) {
    return value.text.trim();
  }

  if (typeof value.content === 'string' && value.content.trim()) {
    return value.content.trim();
  }

  if (Array.isArray(value.content)) {
    const contentText = value.content
      .map(part => {
        if (!part || typeof part !== 'object') return '';
        return (
          part.text ||
          part.output_text ||
          part.content ||
          ''
        );
      })
      .filter(Boolean)
      .join('\n')
      .trim();

    if (contentText) return contentText;
  }

  if (Array.isArray(value.output)) {
    const outputText = value.output
      .map(item => extractText(item))
      .filter(Boolean)
      .join('\n')
      .trim();

    if (outputText) return outputText;
  }

  if (Array.isArray(value.choices) && value.choices.length > 0) {
    const choice = value.choices[0];

    const choiceText =
      extractText(choice?.message?.content) ||
      extractText(choice?.message) ||
      extractText(choice?.text) ||
      '';

    if (choiceText) return choiceText;
  }

  if (typeof value.message === 'object' && value.message) {
    const messageText = extractText(value.message.content || value.message.text || value.message);
    if (messageText) return messageText;
  }

  return '';
}

const replyText = extractText(ai);

return {
  json: {
    replyText,
    reply_text: replyText,
    has_reply_text: !!replyText,
    raw_llm_result: ai
  }
};

const input = $input.first().json;
const leadState = $('Check Lead State').first().json || {};
const currentState = String(leadState.current_state || 'IDLE').toUpperCase();
const lastMessageAt = leadState.previous_last_message_at ? new Date(leadState.previous_last_message_at).getTime() : 0;
const minutesSinceLastKnownMessage = lastMessageAt ? Math.floor((Date.now() - lastMessageAt) / 60000) : null;
let shouldSendJoinForm = true;
let guardReason = 'first_join_invite';
let replyText = input.replyText;
if (currentState === 'AWAITING_FORM') {
