const ctx = $('Build Human WhatsApp Context').first().json || {};
const parsed = $('Parse LLM Result').first()?.json || {};

const buildContext = ctx.build_context || {};
const humanContext = ctx.human_whatsapp_context || {};

const userMessage = String(ctx.userMessage || humanContext.userMessage || '').trim();
const answerMode = String(ctx.answerMode || humanContext.answerMode || 'normal_info');
const primaryFactType = String(ctx.primaryFactType || humanContext.primaryFactType || 'general');

const primaryFactPayload = humanContext.primaryFactPayload || {};
const fallbackFactPayload = humanContext.fallbackFactPayload || {};
const consultativeReplyMode = String(humanContext.consultativeReplyMode || 'normal_info');
const safeGuidanceText = String(humanContext.safeGuidanceText || '').trim();
const adminHandoffText = String(humanContext.adminHandoffText || '').trim();

const hardRules = Array.isArray(humanContext.hardRules) ? humanContext.hardRules : [];
const humanizerHints = Array.isArray(humanContext.humanizerHints) ? humanContext.humanizerHints : [];
const replyGuardrails = Array.isArray(humanContext.replyGuardrails) ? humanContext.replyGuardrails : [];

const responseGoal = String(buildContext.response_goal || 'Jawab kebutuhan user dengan natural.');
const responseScope = String(buildContext.response_scope || 'Jawab seperlunya sesuai pertanyaan user.');
const styleMode = String(buildContext.style_mode || 'natural_admin_whatsapp');
const ctaMode = String(buildContext.cta_mode || 'soft_optional');
const shouldMentionAdmin = !!buildContext.should_mention_admin;
const shouldMentionForm = !!buildContext.should_mention_form;
const shouldOfferFollowUp = !!buildContext.should_offer_follow_up;

function safeJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return '{}';
  }
}

const prompt = `
Kamu adalah admin WhatsApp StepUp Ladies Gym yang membalas chat user dengan gaya natural, hangat, singkat, dan manusiawi.

Tugasmu:
- Susun jawaban final untuk user berdasarkan fakta yang sudah disiapkan.
- Fokus menjawab pertanyaan user, jangan melebar.
- Jangan membuat keputusan baru di luar data dan aturan.

Konteks user:
- Pesan user: ${userMessage}
- Mode jawaban: ${answerMode}
- Tipe fakta utama: ${primaryFactType}
- Style mode: ${styleMode}
- Consultative mode: ${consultativeReplyMode}

Tujuan jawaban:
${responseGoal}

Batas scope jawaban:
${responseScope}

Aturan utama:
${hardRules.map(rule => `- ${rule}`).join('\n')}

Guardrail tambahan:
${replyGuardrails.map(rule => `- ${rule}`).join('\n')}

Gaya bahasa:
${humanizerHints.map(hint => `- ${hint}`).join('\n')}

Panduan konsultatif:
- ${safeGuidanceText || 'Gunakan gaya konsultatif hanya jika memang diperlukan.'}
- ${adminHandoffText || 'Tidak perlu handoff jika pertanyaan masih bisa dijawab langsung.'}

Aturan operasional penting:
- ${shouldMentionAdmin ? 'Boleh menyebut admin jika memang diperlukan sesuai konteks.' : 'Jangan menyuruh user hubungi admin resmi jika pertanyaan masih bisa dijawab langsung.'}
- ${shouldMentionForm ? 'Boleh arahkan ke langkah pendaftaran atau isi data karena user sudah jelas ingin join/daftar.' : 'Jangan meminta user isi data pendaftaran kecuali user memang sudah jelas mau join atau daftar.'}
- ${shouldOfferFollowUp ? 'Boleh tutup dengan pertanyaan follow-up ringan jika relevan.' : 'Tidak perlu CTA tambahan kalau tidak perlu.'}
- CTA mode: ${ctaMode}

Fakta utama:
${safeJson(primaryFactPayload)}

Fakta cadangan:
${safeJson(fallbackFactPayload)}

Instruksi output:
- Tulis hanya 1 balasan final untuk user.
- Plain text saja.
- Jangan pakai markdown.
- Jangan pakai bullet kecuali memang perlu daftar.
- Jangan terdengar seperti brosur.
- Jangan mengulang kalimat yang sama.
- Jangan menambahkan informasi yang tidak ada di fakta.
`;

return {
  json: {
    ...ctx,
    humanizer_final_prompt: prompt,
    prompt_metadata: {
      answer_mode: answerMode,
      primary_fact_type: primaryFactType,
      style_mode: styleMode,
      consultative_reply_mode: consultativeReplyMode,
      should_mention_admin: shouldMentionAdmin,
      should_mention_form: shouldMentionForm,
      should_offer_follow_up: shouldOfferFollowUp
    },
    last_parsed_llm_result: parsed
  }
};

