const msg = String($json.userMessage || '').trim();
const lower = msg.toLowerCase();

function hasLabel(label) {
  return new RegExp('(^|\\n)\\s*' + label + '\\s*:', 'i').test(msg);
}

const formLabelCount = ['nama', 'domisili', 'berat badan', 'bb', 'tinggi badan', 'tb', 'goals', 'goal', 'alasan'].filter(hasLabel).length;
const asksInfo = /(apa saja|apa aja|harga|berapa|biaya|promo|free trial|trial|kelas|program|jadwal|jam|hari|kapan|lokasi|alamat|dimana|fasilitas|coach|special class|\?)/i.test(lower);
const looksLikeFilledForm = formLabelCount >= 3;

return {
  json: {
    ...$json,
    is_actual_join_form: looksLikeFilledForm && !asksInfo,
    awaitingFormRouteReason: looksLikeFilledForm ? 'looks_like_form' : (asksInfo ? 'info_question_while_awaiting_form' : 'not_form')
  }
};

const msg = $('Classify Conversation Micro Intent').first().json || $json;
const rawUserMessage = String(msg.raw_user_message || msg.userMessage || '').trim();
const text = rawUserMessage.toLowerCase();

function matchAny(patterns) {
  return patterns.find((pattern) => pattern.test(text)) || null;
}

const ackMap = [
  {
    type: 'thanks',
    patterns: [
      /\bterima kasih\b/i,
      /\bmakasih\b/i,
      /\bmakasi\b/i,
      /\bthanks\b/i,
      /\bthank you\b/i,
      /\bty\b/i
    ]
  },
  {
    type: 'confirmation',
    patterns: [
      /\boke\b/i,
      /\bok\b/i,
      /\bokay\b/i,
      /\bokey\b/i,
      /\bokee\b/i,
      /\bsiap\b/i,
      /\bsip\b/i,
      /\bnoted\b/i,
      /\bsiap kak\b/i,
      /\bbaik kak\b/i,
      /\boke kak\b/i,
      /\bok kak\b/i
    ]
  },
  {
    type: 'closing',
    patterns: [
      /\bbaik\b/i,
      /\bsiap ya\b/i,
      /\bokay kak\b/i,
      /\bokee kak\b/i
    ]
  }
];

let ackType = '';
let isAcknowledgement = false;

for (const group of ackMap) {
  const found = matchAny(group.patterns);
  if (found) {
    ackType = group.type;
    isAcknowledgement = true;
    break;
  }
}

const isShortReply = rawUserMessage.length > 0 && rawUserMessage.length <= 25;

let suggestedResponseType = 'none';
let acknowledgementMode = 'none';

if (isAcknowledgement) {
  if (ackType === 'thanks') {
    suggestedResponseType = 'warm_ack';
    acknowledgementMode = 'no_need_to_push';
  } else if (ackType === 'confirmation') {
    suggestedResponseType = 'light_confirm';
    acknowledgementMode = 'offer_if_needed';
  } else if (ackType === 'closing') {
    suggestedResponseType = 'soft_close';
    acknowledgementMode = 'close_politely';
  }
}

const canAutoReply =
  isAcknowledgement &&
  isShortReply &&
  !msg.is_consultation_intent &&
  !msg.is_join_intent &&
  !msg.is_ambiguous_intent;

return {
  json: {
    ...msg,
    is_acknowledgement: isAcknowledgement,
    ack_type: ackType || null,
    is_short_reply: isShortReply,
    suggested_ack_response_type: suggestedResponseType,
    acknowledgement_mode: acknowledgementMode,
    can_auto_reply_ack: canAutoReply
  }
};

const msg = $('Detect Acknowledgement').first().json || $json;
const rawUserMessage = String(msg.raw_user_message || msg.userMessage || '').trim();
const text = rawUserMessage.toLowerCase();

function hasAny(patterns) {
  return patterns.some((pattern) => pattern.test(text));
}

const consultationPatterns = [
  /\bkonsul\b/i,
  /\bkonsultasi\b/i,
  /\bmau konsultasi\b/i,
  /\bpengen konsultasi\b/i,
  /\bingin konsultasi\b/i,
  /\bminta saran\b/i,
  /\bsaran\b/i,
  /\brekomendasi\b/i,
  /\bmenurut kak\b/i,
  /\bgimana baiknya\b/i,
  /\bbingung pilih\b/i,
  /\bcocok yang mana\b/i,
  /\bsebaiknya\b/i,
  /\barahan\b/i,
  /\bbisa bantu pilih\b/i
];

const bodyGoalPatterns = [
  /\bturun berat badan\b/i,
  /\bnaik berat badan\b/i,
  /\bmenurunkan berat badan\b/i,
  /\bmembentuk tubuh\b/i,
  /\bmengencangkan\b/i,
  /\bmengecilkan\b/i,
  /\bperut\b/i,
  /\bpinggang\b/i,
  /\bpostur\b/i,
  /\bbakar lemak\b/i,
  /\bfit\b/i,
  /\bsehat\b/i,
  /\btarget\b/i,
  /\bgoals?\b/i
];

const conditionNarrativePatterns = [
  /\bdulu pernah\b/i,
  /\bsebelumnya\b/i,
  /\bhabis\b/i,
  /\bsetelah\b/i,
  /\bsaat ini\b/i,
  /\bsekarang\b/i,
  /\bmasih\b/i,
  /\bbelum berani\b/i,
  /\bpengen mulai\b/i,
  /\bmau mulai\b/i,
  /\bkondisi\b/i,
  /\bcerita\b/i
];

const productOrProgramSelectionPatterns = [
  /\bpakai produk\b/i,
  /\bproduk yang mana\b/i,
  /\bprogram yang mana\b/i,
  /\bpaket yang mana\b/i,
  /\bcocok program apa\b/i,
  /\bcocok paket apa\b/i,
  /\bmulai dari mana\b/i,
  /\bmana yang cocok\b/i
];

const explicitConsultation = hasAny(consultationPatterns);
const hasGoalContext = hasAny(bodyGoalPatterns);
const hasNarrativeContext = hasAny(conditionNarrativePatterns);
const hasSelectionContext = hasAny(productOrProgramSelectionPatterns);

const longMessage = rawUserMessage.length >= 80;

const needsConsultation =
  msg.is_consultation_intent ||
  explicitConsultation ||
  (hasGoalContext && hasNarrativeContext) ||
  hasSelectionContext ||
  (longMessage && (hasGoalContext || hasNarrativeContext));

let consultationTopic = null;

if (/produk|herbalife|shake|teh/i.test(text)) {
  consultationTopic = 'nutrition_product';
} else if (/paket|program|kelas|latihan/i.test(text) && hasSelectionContext) {
  consultationTopic = 'program_selection';
} else if (hasGoalContext) {
  consultationTopic = 'body_goal';
} else if (explicitConsultation) {
  consultationTopic = 'general_consultation';
}

let consultationPriority = 'low';
if (needsConsultation && longMessage) consultationPriority = 'medium';
if (needsConsultation && (hasGoalContext && hasNarrativeContext)) consultationPriority = 'high';

const shouldAvoidDirectCatalogReply =
  needsConsultation &&
  !msg.is_acknowledgement &&
  !msg.is_greeting_only;

return {
  json: {
    ...msg,
    needs_consultation: needsConsultation,
    consultation_topic: consultationTopic,
    consultation_priority: consultationPriority,
    has_goal_context: hasGoalContext,
    has_narrative_context: hasNarrativeContext,
    has_selection_context: hasSelectionContext,
    explicit_consultation_request: explicitConsultation,
    should_avoid_direct_catalog_reply: shouldAvoidDirectCatalogReply
  }
};

const msg = $('Consultation Need Detector').first().json || $json;
const rawUserMessage = String(msg.raw_user_message || msg.userMessage || '').trim();
const text = rawUserMessage.toLowerCase();

const riskFlags = [];

function pushFlag(flag, patterns) {
  if (patterns.some((pattern) => pattern.test(text))) {
    riskFlags.push(flag);
  }
}

pushFlag('postpartum', [
  /\bmelahirkan\b/i,
  /\bhabis lahiran\b/i,
  /\bpasca melahirkan\b/i,
  /\bpostpartum\b/i,
  /\bsetelah lahiran\b/i
]);

pushFlag('c_section', [
  /\bsc\b/i,
  /\bsesar\b/i,
  /\bsectio\b/i,
  /\bcaesar\b/i
]);

pushFlag('pain_or_injury', [
  /\bsakit\b/i,
  /\bnyeri\b/i,
  /\bcedera\b/i,
  /\bjahitan\b/i,
  /\bbermasalah\b/i,
  /\bngilu\b/i,
  /\bterasa sakit\b/i
]);

pushFlag('fear_to_exercise', [
  /\bbelum berani olahraga\b/i,
  /\btakut olahraga\b/i,
  /\bgak berani olahraga\b/i,
  /\bnggak berani olahraga\b/i,
  /\btakut mulai\b/i
]);

pushFlag('medical_or_recovery_context', [
  /\bpemulihan\b/i,
  /\brecovery\b/i,
  /\bkontrol\b/i,
  /\bkonsul lagi\b/i,
  /\bdokter\b/i,
  /\bterapi\b/i
]);

pushFlag('nutrition_only_preference', [
  /\bpake herbalife dulu\b/i,
  /\bpakai herbalife dulu\b/i,
  /\bshake dulu\b/i,
  /\bproduk dulu\b/i,
  /\btehnya\b/i,
  /\bherbalife\b/i
]);

const hasSensitiveCondition = riskFlags.length > 0;

const safeModeRequired =
  hasSensitiveCondition ||
  (msg.needs_consultation && msg.consultation_priority === 'high');

let recommendedHandling = 'normal_info';

if (hasSensitiveCondition) {
  recommendedHandling = 'empathetic_consultative';
}

if (
  riskFlags.includes('postpartum') ||
  riskFlags.includes('c_section') ||
  riskFlags.includes('pain_or_injury')
) {
  recommendedHandling = 'admin_or_coach_handoff';
}

const shouldBlockDirectRecommendation =
  hasSensitiveCondition &&
  (
    riskFlags.includes('postpartum') ||
    riskFlags.includes('c_section') ||
    riskFlags.includes('pain_or_injury') ||
    riskFlags.includes('medical_or_recovery_context')
  );

return {
  json: {
    ...msg,
    has_sensitive_condition: hasSensitiveCondition,
    risk_flags: riskFlags,
    safe_mode_required: safeModeRequired,
    recommended_handling: recommendedHandling,
    should_block_direct_recommendation: shouldBlockDirectRecommendation
  }
};

const msg =
  $('Sensitive Condition').first().json ||
  $('Consultation Need Detector').first().json ||
  $('Detect Acknowledgement').first().json ||
  $('Classify Conversation Micro Intent').first().json ||
  $('Normalize Incoming Message').first().json ||
  {};

const rawUserMessage = String(
  msg.raw_user_message ||
  msg.userMessage ||
  ''
).trim();

const userText = rawUserMessage.toLowerCase();

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json).filter(Boolean);
  } catch (e) {
    return [];
  }
}

const olahragaRows = safeGet('Fetch Sheet Olahraga').filter(row => {
  const status = String(row.status || row.Status || '').toLowerCase().trim();
  return !status || status === 'aktif' || status === 'active';
});

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function splitAliases(value) {
  return String(value || '')
    .split(/[,/|;]/)
    .map(v => normalizeText(v))
    .filter(Boolean);
}

function hasClassDetailCue(text) {
  return [
    /\bitu kayak gimana\b/i,
    /\bapa itu\b/i,
    /\bapa sih\b/i,
    /\bseperti apa\b/i,
    /\bjelasin\b/i,
    /\bpenjelasan\b/i,
    /\bdetail\b/i,
    /\bmaksudnya\b/i,
    /\buntuk apa\b/i,
    /\bkelas apa\b/i,
    /\bbedanya apa\b/i,
    /\bmanfaatnya\b/i,
    /\bcocok untuk siapa\b/i,
    /\blevelnya\b/i,
    /\bapa manfaatnya\b/i
  ].some(pattern => pattern.test(text));
}

const normalizedUser = normalizeText(userText);
const userTokens = normalizedUser.split(' ').filter(Boolean);

function scoreMatch(row) {
  const namaOlahraga = String(row.nama_olahraga || row['Nama Olahraga'] || '').trim();
  const aliasRaw = String(row.alias || row.Alias || '').trim();

  const normalizedName = normalizeText(namaOlahraga);
  const aliases = splitAliases(aliasRaw);

  let score = 0;
  let matchedBy = null;
  let matchedValue = null;

  if (!normalizedName) {
    return { row, score: 0, matchedBy, matchedValue };
  }

  if (normalizedUser === normalizedName) {
    score += 200;
    matchedBy = 'nama_exact';
    matchedValue = namaOlahraga;
  }

  if (normalizedUser.includes(normalizedName)) {
    score += 120;
    matchedBy = matchedBy || 'nama_in_text';
    matchedValue = matchedValue || namaOlahraga;
  }

  if (normalizedName.includes(normalizedUser) && normalizedUser.length >= 4) {
    score += 60;
    matchedBy = matchedBy || 'nama_partial';
    matchedValue = matchedValue || namaOlahraga;
  }

  for (const alias of aliases) {
    if (!alias) continue;

    if (normalizedUser === alias) {
      score += 180;
      matchedBy = matchedBy || 'alias_exact';
      matchedValue = matchedValue || alias;
    }

    if (normalizedUser.includes(alias)) {
      score += 100;
      matchedBy = matchedBy || 'alias_in_text';
      matchedValue = matchedValue || alias;
    }

    if (alias.includes(normalizedUser) && normalizedUser.length >= 4) {
      score += 50;
      matchedBy = matchedBy || 'alias_partial';
      matchedValue = matchedValue || alias;
    }
  }

  const nameTokens = normalizedName.split(' ').filter(Boolean);
  const matchedTokens = nameTokens.filter(token => userTokens.includes(token));
  if (matchedTokens.length > 0) {
    score += matchedTokens.length * 15;
    matchedBy = matchedBy || 'token_match';
    matchedValue = matchedValue || namaOlahraga;
  }

  if (nameTokens.length > 1 && matchedTokens.length === nameTokens.length) {
    score += 40;
  }

  for (const alias of aliases) {
    const aliasTokens = alias.split(' ').filter(Boolean);
    const aliasMatchedTokens = aliasTokens.filter(token => userTokens.includes(token));
    if (aliasMatchedTokens.length > 0) {
      score += aliasMatchedTokens.length * 10;
      matchedBy = matchedBy || 'alias_token_match';
      matchedValue = matchedValue || alias;
    }
  }

  return { row, score, matchedBy, matchedValue };
}

const scoredMatches = olahragaRows
  .map(scoreMatch)
  .filter(entry => entry.score > 0)
  .sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    const aNameLen = String(a.row.nama_olahraga || '').length;
    const bNameLen = String(b.row.nama_olahraga || '').length;
    return bNameLen - aNameLen;
  });

const bestMatch = scoredMatches[0] || null;
const classMatched = !!(bestMatch && bestMatch.score >= 40);

const classDetailIntent =
  !!msg.is_class_detail_intent ||
  hasClassDetailCue(userText);

const payload = classMatched
  ? {
      id: bestMatch.row.id || null,
      nama_olahraga: String(bestMatch.row.nama_olahraga || '').trim(),
      alias: String(bestMatch.row.alias || '').trim(),
      deskripsi_singkat: String(bestMatch.row.deskripsi_singkat || '').trim(),
      manfaat: String(bestMatch.row.manfaat || '').trim(),
      cocok_untuk: String(bestMatch.row.cocok_untuk || '').trim(),
      level: String(bestMatch.row.level || '').trim(),
      fokus_latihan: String(bestMatch.row.fokus_latihan || '').trim(),
      status: String(bestMatch.row.status || '').trim()
    }
  : null;

let classDetailResponseMode = 'none';
if (classDetailIntent && classMatched) classDetailResponseMode = 'class_detail_found';
else if (classDetailIntent && !classMatched) classDetailResponseMode = 'class_detail_not_found';

return {
  json: {
    ...msg,
    raw_user_message: rawUserMessage,
    class_detail_intent: classDetailIntent,
    class_detail_found: classMatched,
    class_matched: classMatched,
    matched_class_id: payload ? payload.id : null,
    matched_class_name: payload ? payload.nama_olahraga : null,
    matched_class_alias: payload ? payload.alias : null,
    matched_class_by: classMatched ? bestMatch.matchedBy : null,
    matched_class_score: classMatched ? bestMatch.score : 0,
    class_detail_payload: payload,
    class_detail_response_mode: classDetailResponseMode,
    class_detail_candidates: scoredMatches.slice(0, 3).map(entry => ({
      id: entry.row.id || null,
      nama_olahraga: String(entry.row.nama_olahraga || '').trim(),
      alias: String(entry.row.alias || '').trim(),
      score: entry.score
    }))
  }
};

const collected = $('Collect Reference Data').first()?.json || {};
const eligibility = $('Recommendation Eligibility Checker').first()?.json || {};
const consult = $('Consultation Need Detector').first()?.json || {};
const sensitive = $('Sensitive Condition').first()?.json || {};

const activeDomain = String(collected.active_domain || 'none');
const activeContext = collected.active_domain_context || null;
const referenceData = collected.reference_data || {};

const userMessage = String(
  collected.raw_user_message ||
  collected.userMessage ||
  ''
).trim();

const joinRef = referenceData.join || {};
const hargaRef = referenceData.harga_event_promo || {};
const jadwalRef = referenceData.jadwal_coach || {};
const olahragaRef = referenceData.olahraga || {};
const kbRef = referenceData.knowledge_base || {};

let primaryFactType = 'general';
let primaryFactPayload = null;
let fallbackFactPayload = {};
let answerMode = 'normal_info';

if (activeDomain === 'join') {
  primaryFactType = 'join';
  answerMode = joinRef.join_ready_for_form ? 'join_flow' : 'join_info';

  primaryFactPayload = {
    context: joinRef.context || null,
    flags: joinRef.flags || {},
    join_ready_for_form: !!joinRef.join_ready_for_form,
    join_info_only: !!joinRef.join_info_only
  };
}

else if (activeDomain === 'harga_event_promo') {
  primaryFactType = 'harga_event_promo';

  const hasHarga = Array.isArray(hargaRef.harga_rows) && hargaRef.harga_rows.length > 0;
  const hasPromo = Array.isArray(hargaRef.promo_rows) && hargaRef.promo_rows.length > 0;
  const hasEvent = Array.isArray(hargaRef.event_rows) && hargaRef.event_rows.length > 0;

  if (hasPromo && !hasHarga && !hasEvent) {
    answerMode = 'promo_info';
  } else if (hasEvent && !hasHarga && !hasPromo) {
    answerMode = 'event_info';
  } else {
    answerMode = 'price_info';
  }

  primaryFactPayload = {
    context: hargaRef.context || null,
    flags: hargaRef.flags || {},
    harga_rows: hasHarga ? hargaRef.harga_rows : [],
    promo_rows: hasPromo ? hargaRef.promo_rows : [],
    event_rows: hasEvent ? hargaRef.event_rows : []
  };
}

else if (activeDomain === 'jadwal_coach') {
  primaryFactType = 'jadwal_coach';

  const asksCoach = !!jadwalRef.flags?.asks_coach;
  const hasScheduleRows = Array.isArray(jadwalRef.schedule_rows) && jadwalRef.schedule_rows.length > 0;
  const hasCoachRows = Array.isArray(jadwalRef.coach_rows) && jadwalRef.coach_rows.length > 0;

  if (asksCoach && hasCoachRows) {
    answerMode = 'coach_info';
  } else if (hasScheduleRows) {
    answerMode = 'schedule_info';
  } else {
    answerMode = 'schedule_info';
  }

  primaryFactPayload = {
    context: jadwalRef.context || null,
    flags: jadwalRef.flags || {},
    schedule_rows: hasScheduleRows ? jadwalRef.schedule_rows : [],
    coach_rows: hasCoachRows ? jadwalRef.coach_rows : [],
    coach_names: Array.isArray(jadwalRef.coach_names) ? jadwalRef.coach_names : [],
    coach_keywords: Array.isArray(jadwalRef.coach_keywords) ? jadwalRef.coach_keywords : []
  };
}

else if (activeDomain === 'olahraga') {
  primaryFactType = 'olahraga';
  answerMode = 'class_detail';

  primaryFactPayload = {
    context: olahragaRef.context || null,
    flags: olahragaRef.flags || {},
    class_detail_payload: olahragaRef.class_detail_payload || null,
    class_detail_candidates: Array.isArray(olahragaRef.class_detail_candidates)
      ? olahragaRef.class_detail_candidates
      : []
  };
}

else if (activeDomain === 'knowledge_base') {
  primaryFactType = 'knowledge_base';

  const kbType = String(kbRef.context?.type || 'general_kb');

  if (kbType === 'location_info') {
    answerMode = 'location_info';
  } else if (kbType === 'admin_info') {
    answerMode = 'admin_info';
  } else if (kbType === 'about_gym') {
    answerMode = 'about_info';
  } else if (kbType === 'social_info') {
    answerMode = 'social_info';
  } else if (kbType === 'registration_info') {
    answerMode = 'registration_info';
  } else if (kbType === 'consultation_info') {
    answerMode = 'consultation_info';
  } else {
    answerMode = 'general_info';
  }

  primaryFactPayload = {
    context: kbRef.context || null,
    flags: kbRef.flags || {},
    kb_rows: Array.isArray(kbRef.kb_rows) ? kbRef.kb_rows : [],
    location_text: String(kbRef.location_text || '').trim(),
    admin_text: String(kbRef.admin_text || '').trim(),
    social_text: String(kbRef.social_text || '').trim(),
    about_text: String(kbRef.about_text || '').trim()
  };
}

fallbackFactPayload = {
  active_domain: activeDomain,
  active_context: activeContext,
  collected_reference_summary: collected.collected_reference_summary || {},
  consultation: {
    needs_consultation: !!consult.needs_consultation,
    consultation_topic: String(consult.consultation_topic || ''),
    consultation_priority: String(consult.consultation_priority || 'low')
  },
  sensitive: {
    has_sensitive_condition: !!sensitive.has_sensitive_condition,
    risk_flags: Array.isArray(sensitive.risk_flags) ? sensitive.risk_flags : [],
    safe_mode_required: !!sensitive.safe_mode_required
  },
  eligibility: {
    can_recommend_directly: !!eligibility.can_recommend_directly,
    recommendation_mode: String(eligibility.recommendation_mode || 'direct_answer_allowed'),
    consultation_response_type: String(eligibility.consultation_response_type || 'normal_info'),
    eligibility_reason: String(eligibility.eligibility_reason || '')
  }
};

return {
  json: {
    ...collected,
    answer_mode: answerMode,
    primary_fact_type: primaryFactType,
    primary_fact_payload: primaryFactPayload,
    fallback_fact_payload: fallbackFactPayload,
    answer_facts: {
      userMessage,
      answerMode,
      primaryFactType,
      primaryFactPayload,
      fallbackFactPayload
    }
  }
};

