const userMessage = String(ctx.userMessage || '').trim();

const buildContext = ctx.build_context || {};
const shouldMentionAdmin = !!buildContext.should_mention_admin;
const shouldMentionForm = !!buildContext.should_mention_form;
const shouldOfferFollowUp = !!buildContext.should_offer_follow_up;

const referenceData = collected.reference_data || {};
const jadwalRef = referenceData.jadwal_coach || {};

let replyText = String(
  styled.replyText ||
  styled.reply_text ||
  styled.output_text ||
  styled.text ||
  styled.content ||
  ''
).trim();

function cleanSpaces(text) {
  return String(text || '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function removeForbiddenAdminHandoff(text) {
  if (shouldMentionAdmin) return text;

  return text
    .replace(/\s*(silakan|bisa|boleh)?\s*hubungi admin resmi kami[^.?!]*[.?!]?/gi, '')
    .replace(/\s*(silakan|bisa|boleh)?\s*hubungi admin kami[^.?!]*[.?!]?/gi, '')
    .replace(/\s*(untuk info lebih lanjut|untuk proses selanjutnya),?\s*hubungi admin[^.?!]*[.?!]?/gi, '')
    .replace(/\s*(nanti|selanjutnya)?\s*akan dibantu admin[^.?!]*[.?!]?/gi, '');
}

function removeForbiddenFormCTA(text) {
  if (shouldMentionForm) return text;

  return text
    .replace(/\s*jangan lupa isi data pendaftaran[^.?!]*[.?!]?/gi, '')
    .replace(/\s*silakan isi data pendaftaran[^.?!]*[.?!]?/gi, '')
    .replace(/\s*bisa isi data pendaftaran[^.?!]*[.?!]?/gi, '')
    .replace(/\s*isi form pendaftaran[^.?!]*[.?!]?/gi, '')
    .replace(/\s*isi data diri dulu[^.?!]*[.?!]?/gi, '');
}

function removeExtraCTA(text) {
  if (shouldOfferFollowUp) return text;

  return text
    .replace(/\s*ada yang ingin (ditanyakan|kamu tanyakan) lagi[^.?!]*[.?!]?/gi, '')
    .replace(/\s*kalau ada yang ingin ditanyakan lagi[^.?!]*[.?!]?/gi, '')
    .replace(/\s*semoga membantu ya[^.?!]*[.?!]?/gi, '')
    .trim();
}

function removeDoubleGreeting(text) {
  const lines = String(text || '').split('\n');
  if (lines.length === 0) return text;

  let firstLine = lines[0]
    .replace(/^(hai|halo|hi)\s+kak,\s*(selamat pagi|selamat siang|selamat sore|selamat malam)/i, '$2 kak')
    .replace(/^(pagi|siang|sore|malam)\s+kak,\s*(selamat pagi|selamat siang|selamat sore|selamat malam)/i, '$2 kak')
    .replace(/^(selamat pagi|selamat siang|selamat sore|selamat malam),\s*(hai|halo|hi)\s+kak/i, '$1 kak');

  lines[0] = firstLine;
  return lines.join('\n');
}

function ensureTodayScheduleCompleteness(text) {
  if (answerMode !== 'schedule_info') return text;

  const asksToday = !!jadwalRef.flags?.asks_schedule_for_today;
  const rows = Array.isArray(jadwalRef.schedule_rows) ? jadwalRef.schedule_rows : [];

  if (!asksToday || rows.length === 0) return text;

  const missingRows = rows.filter(row => {
    const kelas = String(row.kelas || '').trim().toLowerCase();
    return kelas && !text.toLowerCase().includes(kelas);
  });

  if (missingRows.length === 0) return text;

  const scheduleList = rows
    .map(row => {
      const kelas = String(row.kelas || '').trim();
      const jam = String(row.jam || '').trim();
      const coach = String(row.coach || '').trim();
      if (kelas && jam && coach) return `${kelas} jam ${jam} dengan coach ${coach}`;
      if (kelas && jam) return `${kelas} jam ${jam}`;
      return kelas;
    })
    .filter(Boolean)
    .join(', ');

  if (!scheduleList) return text;

  return `Hari ini ada ${scheduleList}.`;
}

replyText = removeForbiddenAdminHandoff(replyText);
replyText = removeForbiddenFormCTA(replyText);
replyText = removeExtraCTA(replyText);
replyText = removeDoubleGreeting(replyText);
replyText = cleanSpaces(replyText);
replyText = ensureTodayScheduleCompleteness(replyText);
replyText = cleanSpaces(replyText);

return {
