  recommendationMode = 'direct_answer_allowed';
  consultationResponseType = 'direct_reference_answer';
  eligibilityReason = 'reference_question_safe';

} else if ((isJoinIntent || isInfoRequest) && !hasSensitiveCondition && !safeModeRequired) {
  canRecommendDirectly = true;
  recommendationMode = 'direct_answer_allowed';
  consultationResponseType = isJoinIntent ? 'join_guidance' : 'informational_guidance';
  eligibilityReason = isJoinIntent ? 'join_intent_safe' : 'informational_request_safe';

} else if (shouldBlockDirectRecommendation) {
  canRecommendDirectly = false;
  recommendationMode = 'handoff_required';
  mustHandoffAdmin = true;
  mustHandoffCoach = true;
  consultationResponseType = 'empathetic_handoff';
  eligibilityReason = 'sensitive_condition_blocks_recommendation';

} else if (hasSensitiveCondition || safeModeRequired) {
