  recommendationMode = 'general_guidance_only';
  mustHandoffAdmin = true;
  consultationResponseType = 'consultative_guidance';
  eligibilityReason = 'high_priority_consultation';

} else if (needsConsultation && consultationPriority === 'medium') {
  canRecommendDirectly = false;
  recommendationMode = 'general_guidance_only';
  consultationResponseType = 'consultative_guidance';
  eligibilityReason = 'medium_priority_consultation';

