  item.userMessage ||
  ''
).trim();

const userText = rawUserMessage.toLowerCase();

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function titleCaseDay(day) {
  const map = {
    senin: 'Senin',
    selasa: 'Selasa',
    rabu: 'Rabu',
    kamis: 'Kamis',
    jumat: 'Jumat',
    sabtu: 'Sabtu',
    minggu: 'Minggu'
  };
  return map[day] || null;
}

function normalizeDayToken(day) {
  return normalizeText(day).replace(/^jum at$/i, 'jumat');
}

const nowJkt = new Date(
  new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' })
);

const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const currentDayName = dayNames[nowJkt.getDay()];
const currentDayNormalized = normalizeDayToken(currentDayName);

const resolvedUserText = userText
  .replace(/\bhari ini\b/g, currentDayNormalized)
  .replace(/\bsekarang\b(?=.*jadwal)/g, currentDayNormalized)
  .replace(/\bjum'at\b/g, 'jumat');

const dayRegex = /\bsenin\b|\bselasa\b|\brabu\b|\bkamis\b|\bjumat\b|\bjum'at\b|\bsabtu\b|\bminggu\b/gi;
const dayMatchesRaw = resolvedUserText.match(dayRegex) || [];
const uniqueDays = [...new Set(dayMatchesRaw.map(normalizeDayToken).filter(Boolean))];
const matchedDay = uniqueDays.length > 0 ? titleCaseDay(uniqueDays[0]) : null;

const hasScheduleKeyword =
  /\bjadwal\b|\bjam\b|\bkapan\b|\bhari\b|\bsetiap hari\b|\btiap hari\b|\bopen class\b/.test(userText);

const wantsFullSchedule =
  /\bjadwal lengkap\b|\bjadwal full\b|\bjadwal semua\b|\bsemua jadwal\b|\blist jadwal\b|\bdaftar jadwal\b|\bsemua kelas\b/.test(userText);

const asksClassExistenceByDay =
  /\bada\b.*\b(senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu)\b|\b(senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu)\b.*\bada\b/.test(userText);

const asksEveryDay =
  /\bsetiap hari\b|\btiap hari\b|\beveryday\b|\bevery day\b/.test(userText);

const matchedClassName = String(
  classDetail.matched_class_name ||
  classDetail.matched_class ||
  classDetail.class_detail_payload?.nama_olahraga ||
  ''
).trim();

const classFound = !!(
  (classDetail.class_matched || classDetail.class_detail_found) &&
  matchedClassName
);

const coachQuestion =
  /\bcoach\b|\bpelatih\b|\btrainer\b|\binstruktur\b|\bsiapa yang ngajar\b|\bsiapa coachnya\b/.test(userText);

const pureCoachQuestion = coachQuestion && !hasScheduleKeyword;

const classDetailQuestion =
  !!classDetail.class_detail_intent &&
  !hasScheduleKeyword &&
  !matchedDay &&
  !asksEveryDay &&
  !asksClassExistenceByDay;

let scheduleIntent = false;
let scheduleQueryType = 'none';

if (!pureCoachQuestion && !classDetailQuestion) {
  if (wantsFullSchedule) {
    scheduleIntent = true;
    scheduleQueryType = 'full_schedule';
  } else if (classFound && matchedDay) {
    scheduleIntent = true;
    scheduleQueryType = 'class_and_day';
  } else if (classFound && (hasScheduleKeyword || asksEveryDay || asksClassExistenceByDay)) {
    scheduleIntent = true;
    scheduleQueryType = 'class_only';
  } else if (!classFound && matchedDay && hasScheduleKeyword) {
    scheduleIntent = true;
    scheduleQueryType = 'day_only';
  } else if (!classFound && matchedDay && /\bkelas\b|\bclass\b/.test(userText)) {
    scheduleIntent = true;
    scheduleQueryType = 'day_only';
  } else if (!classFound && hasScheduleKeyword) {
    scheduleIntent = true;
    scheduleQueryType = 'general_schedule';
  }
}

const asksScheduleForToday =
  /\bhari ini\b|\btoday\b|\bsekarang\b(?=.*jadwal)/.test(userText);

const scheduleScope = classFound
  ? 'specific_class'
  : matchedDay
    ? 'specific_day'
    : wantsFullSchedule
      ? 'full_list'
      : scheduleIntent
        ? 'general'
        : 'none';

const debug = {
  raw_user_message: rawUserMessage,
  resolved_user_text: resolvedUserText,
  class_found: classFound,
  matched_class_name: matchedClassName || null,
  detected_days: uniqueDays,
  matched_day: matchedDay,
  has_schedule_keyword: hasScheduleKeyword,
  pure_coach_question: pureCoachQuestion,
  class_detail_question: classDetailQuestion,
  wants_full_schedule: wantsFullSchedule,
  asks_every_day: asksEveryDay,
  asks_schedule_for_today: asksScheduleForToday
};

return {
  json: {
    ...item,
    raw_user_message: rawUserMessage,
    resolved_user_text: resolvedUserText,
    schedule_intent: scheduleIntent,
    needs_schedule_resolution: scheduleIntent,
    matched_schedule_class: classFound ? matchedClassName : null,
    matched_schedule_day: matchedDay,
    matched_schedule_days: uniqueDays.map(titleCaseDay).filter(Boolean),
    schedule_query_type: scheduleQueryType,
    schedule_scope: scheduleScope,
    asks_every_day_schedule: asksEveryDay,
    wants_full_schedule: wantsFullSchedule,
    asks_schedule_for_today: asksScheduleForToday,
    schedule_debug: debug
  }
};

const item = $input.first().json || {};

const scheduleQuery =
  $('Resolve Schedule Query').first().json ||
  item;

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(Boolean);
  } catch (e) {
    return [];
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDay(value) {
  const v = normalizeText(value).replace(/^jum at$/i, 'jumat');
  const map = {
    senin: 'Senin',
    selasa: 'Selasa',
    rabu: 'Rabu',
    kamis: 'Kamis',
    jumat: 'Jumat',
    sabtu: 'Sabtu',
    minggu: 'Minggu'
  };
  return map[v] || null;
}

function daySortValue(day) {
  const order = {
    senin: 1,
    selasa: 2,
    rabu: 3,
    kamis: 4,
    jumat: 5,
    sabtu: 6,
    minggu: 7
  };
  return order[normalizeText(day)] || 99;
}

function parseTimeForSort(value) {
  const text = String(value || '').trim();
  const match = text.match(/(\d{1,2})[.:](\d{2})/);
  if (!match) return 9999;
  const hh = Number(match[1]);
  const mm = Number(match[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return 9999;
  return (hh * 60) + mm;
}

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase().trim();
  return !s || s === 'aktif' || s === 'active';
}

function pickClassField(row) {
  return String(row.kelas || row.nama_kelas || '').trim();
}

function sortScheduleRows(rows) {
  return [...rows].sort((a, b) => {
    const dayDiff = daySortValue(a.hari) - daySortValue(b.hari);
    if (dayDiff !== 0) return dayDiff;

    const timeDiff = parseTimeForSort(a.jam) - parseTimeForSort(b.jam);
    if (timeDiff !== 0) return timeDiff;

    return pickClassField(a).localeCompare(pickClassField(b));
  });
}

function formatRow(row) {
  const parts = [];
  if (row.hari) parts.push(row.hari);
  if (row.jam) parts.push(`jam ${row.jam}`);
  if (pickClassField(row)) parts.push(pickClassField(row));
  if (row.coach) parts.push(`dengan coach ${row.coach}`);
