  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDay(value) {
  const v = normalizeText(value).replace(/^jum at$/i, 'jumat');
  const map = {
    senin: 'Senin',
    selasa: 'Selasa',
    rabu: 'Rabu',
    kamis: 'Kamis',
    jumat: 'Jumat',
    sabtu: 'Sabtu',
    minggu: 'Minggu'
  };
  return map[v] || null;
}

function splitMultiValue(value) {
  return String(value || '')
    .split(/[,/|;]/)
    .map(v => normalizeText(v))
    .filter(Boolean);
}

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase().trim();
  return !s || s === 'aktif' || s === 'active';
}

function pickClassField(row) {
  return String(row.kelas || row.nama_kelas || '').trim();
}

function daySortValue(day) {
  const order = {
    senin: 1,
    selasa: 2,
    rabu: 3,
    kamis: 4,
    jumat: 5,
    sabtu: 6,
    minggu: 7
  };
  return order[normalizeText(day)] || 99;
}

function parseTimeForSort(value) {
  const text = String(value || '').trim();
  const match = text.match(/(\d{1,2})[.:](\d{2})/);
  if (!match) return 9999;
  const hh = Number(match[1]);
  const mm = Number(match[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return 9999;
  return (hh * 60) + mm;
}

function sortScheduleRows(rows) {
  return [...rows].sort((a, b) => {
    const dayDiff = daySortValue(a.hari) - daySortValue(b.hari);
    if (dayDiff !== 0) return dayDiff;

    const timeDiff = parseTimeForSort(a.jam) - parseTimeForSort(b.jam);
    if (timeDiff !== 0) return timeDiff;

    return pickClassField(a).localeCompare(pickClassField(b));
  });
}

const nowJkt = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
