const normalizedUserMsg = normalizeText(userText);
const normalizedUserTokens = normalizedUserMsg.split(' ').filter(Boolean);

function scoreCoachRow(row) {
  const coachName = String(row.nama_coach || '').trim();
  const normalizedCoachName = normalizeText(coachName);
  const specialistListRaw = splitMultiValue(row.specialist || '');
  const hariMengajarListRaw = splitMultiValue(row.hari_mengajar || '');

  let score = 0;
  let reasons = [];
  let matchedKeywords = [];

  for (const specialist of specialistListRaw) {
    if (!specialist) continue;

    if (normalizedUserMsg === specialist) {
      score += 200;
      reasons.push(`specialist_exact:${specialist}`);
      matchedKeywords.push(specialist);
      continue;
    }

    if (normalizedUserMsg.includes(specialist)) {
      score += 120;
      reasons.push(`specialist_in_text:${specialist}`);
      matchedKeywords.push(specialist);
      continue;
    }

    const specialistTokens = specialist.split(' ').filter(Boolean);
    const matchedTokens = specialistTokens.filter(token => normalizedUserTokens.includes(token));

    if (matchedTokens.length > 0) {
      score += matchedTokens.length * 25;
      reasons.push(`specialist_tokens:${matchedTokens.join(',')}`);
      matchedKeywords.push(...matchedTokens);
    }

    if (specialistTokens.length > 1 && matchedTokens.length === specialistTokens.length) {
      score += 35;
      reasons.push(`specialist_full_tokens:${specialist}`);
    }
  }

  if (normalizedCoachName && normalizedUserMsg.includes(normalizedCoachName)) {
    score += 180;
    reasons.push(`coach_name_in_text:${normalizedCoachName}`);
    matchedKeywords.push(normalizedCoachName);
  }

  for (const dayName of hariMengajarListRaw) {
    if (dayName && normalizedUserMsg.includes(dayName)) {
      score += 8;
      reasons.push(`hari_mengajar:${dayName}`);
      matchedKeywords.push(dayName);
    }
  }

  return {
    row,
    score,
    reasons: [...new Set(reasons)],
    matchedKeywords: [...new Set(matchedKeywords.filter(Boolean))]
  };
}

let matchedCoachRows = [];
let matchedCoachNames = [];
let matchedCoachKeywords = [];
let coachMatchType = 'none';

