    matchedCoachKeywords = [...new Set(
      matchedCoachRows.flatMap(r => Array.isArray(r._coach_match_keywords) ? r._coach_match_keywords : [])
    )];

    coachMatchType = 'specialist_or_name_match';
  } else {
    coachMatchType = 'no_match';
  }
}

