function hasClassDetailCue(text) {
  return /\bitu kayak gimana\b|\bapa itu\b|\bapa sih\b|\bseperti apa\b|\bjelasin\b|\bpenjelasan\b|\bdetail\b|\bmaksudnya\b|\buntuk apa\b|\bbuat apa\b|\bmanfaatnya\b/.test(text);
