    return !status || status === 'aktif' || status === 'active';
  });

const normalizedUser = normalizeText(userText);
const userTokens = normalizedUser.split(' ').filter(Boolean);

function scoreMatch(row) {
  const namaOlahraga = String(row.nama_olahraga || '').trim();
  const aliasRaw = String(row.alias || '').trim();

  const normalizedName = normalizeText(namaOlahraga);
  const aliases = splitAliases(aliasRaw);

  let score = 0;
  let matchedBy = null;
  let matchedValue = null;

  if (!normalizedName) {
    return { row, score: 0, matchedBy: null, matchedValue: null };
  }

  if (normalizedUser === normalizedName) {
    score += 220;
    matchedBy = 'name_exact';
    matchedValue = namaOlahraga;
  }

  if (normalizedUser.includes(normalizedName)) {
    score += 120;
    matchedBy = matchedBy || 'name_in_text';
    matchedValue = matchedValue || namaOlahraga;
  }

  if (normalizedName.includes(normalizedUser) && normalizedUser.length >= 4) {
    score += 50;
    matchedBy = matchedBy || 'name_partial';
    matchedValue = matchedValue || namaOlahraga;
  }

  for (const alias of aliases) {
    if (normalizedUser === alias) {
      score += 180;
      matchedBy = matchedBy || 'alias_exact';
      matchedValue = matchedValue || alias;
    }

    if (normalizedUser.includes(alias)) {
      score += 100;
      matchedBy = matchedBy || 'alias_in_text';
      matchedValue = matchedValue || alias;
    }

    if (alias.includes(normalizedUser) && normalizedUser.length >= 4) {
      score += 50;
      matchedBy = matchedBy || 'alias_partial';
      matchedValue = matchedValue || alias;
    }
  }

  const nameTokens = normalizedName.split(' ').filter(Boolean);
  const matchedTokens = nameTokens.filter(token => userTokens.includes(token));
  if (matchedTokens.length > 0) {
    score += matchedTokens.length * 15;
    matchedBy = matchedBy || 'token_match';
    matchedValue = matchedValue || namaOlahraga;
  }

  if (nameTokens.length > 1 && matchedTokens.length === nameTokens.length) {
    score += 40;
  }

  for (const alias of aliases) {
    const aliasTokens = alias.split(' ').filter(Boolean);
    const aliasMatchedTokens = aliasTokens.filter(token => userTokens.includes(token));
    if (aliasMatchedTokens.length > 0) {
      score += aliasMatchedTokens.length * 10;
      matchedBy = matchedBy || 'alias_token_match';
      matchedValue = matchedValue || alias;
    }
  }

  return { row, score, matchedBy, matchedValue };
}

const scoredMatches = olahragaRows
  .map(scoreMatch)
  .filter(entry => entry.score > 0)
  .sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    const aNameLen = String(a.row.nama_olahraga || '').length;
    const bNameLen = String(b.row.nama_olahraga || '').length;
    return bNameLen - aNameLen;
  });

const bestMatch = scoredMatches[0] || null;
const classMatched = !!(bestMatch && bestMatch.score >= 40);

const explicitClassDetailIntent =
  !!input.is_class_detail_intent ||
  hasClassDetailCue(userText);

const payload = classMatched
  ? {
      id: bestMatch.row.id || null,
