let classDetailResponseMode = 'none';

if (explicitClassDetailIntent && classMatched) {
  classDetailResponseMode = 'class_detail_found';
} else if (explicitClassDetailIntent && !classMatched) {
  classDetailResponseMode = 'class_detail_not_found';
} else if (classMatched) {
  classDetailResponseMode = 'class_detected';
}

return {
  json: {
    ...input,
    route_domain: 'olahraga',

    class_detail_intent: explicitClassDetailIntent,
    class_detail_found: classMatched,
    class_matched: classMatched,

