    matched_class_alias: payload ? payload.alias : null,
    matched_class_by: classMatched ? bestMatch.matchedBy : null,
    matched_class_score: classMatched ? bestMatch.score : 0,

    class_detail_payload: payload,
    class_detail_response_mode: classDetailResponseMode,

    class_detail_candidates: scoredMatches.slice(0, 3).map(entry => ({
      id: entry.row.id || null,
      nama_olahraga: String(entry.row.nama_olahraga || '').trim(),
      alias: String(entry.row.alias || '').trim(),
      score: entry.score
    }))
  }
};

