const input = $json || {};

const rawUserMessage = String(
  input.raw_user_message ||
  input.userMessage ||
  ''
).trim();

const userText = rawUserMessage.toLowerCase();

const isJoinIntent = !!input.is_join_intent;
const isRegistrationInfoIntent = !!input.is_registration_info_intent;

function isExplicitRegistrationRequest(text) {
  const msg = String(text || '').toLowerCase().trim();

  return (
    /\b(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking)\b/i.test(msg) ||
    /\b(mau|ingin|pengen)\s*(daftar|join|gabung)\b/i.test(msg) ||
    /\b(langsung daftar|daftar sekarang|join sekarang|booking sekarang)\b/i.test(msg) ||
    /\b(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)\b/i.test(msg) ||
    /\b(minta|kirim|isi)\s*(form|formulir)\b/i.test(msg) ||
    /^(daftar|join|booking)\b/i.test(msg)
  );
}

function isRegistrationInfoOnly(text) {
  const msg = String(text || '').toLowerCase().trim();

  return (
    /\binfo join\b/i.test(msg) ||
    /\binfo daftar\b/i.test(msg) ||
    /\bjoin kelas\b/i.test(msg) ||
    /\bgabung kelas\b/i.test(msg) ||
    /\bcara daftar\b/i.test(msg) ||
    /\bgimana daftar\b/i.test(msg) ||
    /\bbagaimana daftar\b/i.test(msg) ||
    /\bproses daftar\b/i.test(msg) ||
    /\bsyarat daftar\b/i.test(msg)
  );
}

const explicitRegistration = isExplicitRegistrationRequest(userText);
const registrationInfoOnly = isRegistrationInfoOnly(userText) || isRegistrationInfoIntent;

const shouldSendJoinFlow =
  isJoinIntent &&
  explicitRegistration &&
  !registrationInfoOnly;

const joinRouteMode =
  shouldSendJoinFlow
    ? 'send_join_flow'
    : registrationInfoOnly
      ? 'registration_info_only'
      : 'no_join_action';

return {
  json: {
    ...input,
    route_domain: 'join',
    explicit_registration: explicitRegistration,
    registration_info_only: registrationInfoOnly,
    should_send_join_flow: shouldSendJoinFlow,
    join_route_mode: joinRouteMode
  }
};

